// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface QualityIndicatorsOut {
  date_from: string;
  date_to: string;
  indicators: QualityIndicatorOut[];
  met: number;
  not_met: number;
}

/** A clinical quality indicator for the period, against the hospital's benchmark (MSDS CQI 99-105). */
export interface QualityIndicatorOut {
  code: string;
  group: "Assessment" | "Diagnostics" | "Procedures" | "Medication" | "Anaesthesia" | "Blood" | "Records" | "Outcomes";
  group_title: string;
  title: string;
  /** The MSDS indicator it monitors */
  msds: string;
  unit: "Percent" | "PerThousandPatientDays" | "Count" | "Days";
  better: "Higher" | "Lower" | "Neither";
  numerator: number;
  /** Null for a count */
  denominator: number | null;
  /** Null when nothing could be counted (the denominator is 0) */
  value: number | null;
  target: number | null;
  comparison: "AtLeast" | "AtMost" | null;
  /** False: none of its services runs here and nothing was counted (status NotApplicable; not frozen at the month's end) */
  applies: boolean;
  /** The establishment's services it measures; empty: every establishment */
  services: string[];
  status: "Met" | "NotMet" | "NoTarget" | "NoData" | "NotApplicable";
}

export interface IndicatorTrendOut {
  code: string;
  title: string;
  unit: "Percent" | "PerThousandPatientDays" | "Count" | "Days";
  better: "Higher" | "Lower" | "Neither";
  points: TrendPointOut[];
}

export interface TrendPointOut {
  month: string;
  numerator: number | null;
  denominator: number | null;
  value: number | null;
  target: number | null;
  comparison: "AtLeast" | "AtMost" | null;
  /** False for the current month (live) */
  frozen: boolean;
  status: "Met" | "NotMet" | "NoTarget" | "NoData";
}

export interface IndicatorTargetOut {
  code: string;
  title: string;
  group: string;
  msds: string;
  unit: "Percent" | "PerThousandPatientDays" | "Count" | "Days";
  better: "Higher" | "Lower" | "Neither";
  target: number | null;
  comparison: "AtLeast" | "AtMost" | null;
  note: string | null;
  set_by_name: string | null;
  set_at: string | null;
  row_version: number | null;
}

/** The clinical quality indicators of a period — GET /api/v1/quality/indicators (who may call: holders of quality.indicator.view). */
export function qualityIndicators(query?: { date_from?: string | null; date_to?: string | null }): Promise<QualityIndicatorsOut> {
  return api<QualityIndicatorsOut>("GET", withQuery(`/quality/indicators`, query), undefined);
}

/** The clinical quality indicators report (PDF) — GET /api/v1/quality/indicators/pdf (who may call: holders of quality.indicator.view). */
export function qualityIndicatorsPdf(query?: { date_from?: string | null; date_to?: string | null }): Promise<unknown> {
  return api<unknown>("GET", withQuery(`/quality/indicators/pdf`, query), undefined);
}

/** One indicator month by month — GET /api/v1/quality/indicators/{code}/trend (who may call: holders of quality.indicator.view). */
export function indicatorTrend(code: string, query?: { months?: number }): Promise<IndicatorTrendOut> {
  return api<IndicatorTrendOut>("GET", withQuery(`/quality/indicators/${code}/trend`, query), undefined);
}

/** The hospital's benchmarks for the indicators — GET /api/v1/quality/indicator-targets (who may call: holders of quality.indicator.view). */
export function indicatorTargets(): Promise<IndicatorTargetOut[]> {
  return api<IndicatorTargetOut[]>("GET", `/quality/indicator-targets`, undefined);
}
